// === Tab: mySketch ===
// 引力・斥力モデル
var num = 5000;
var vx = new Array(num);
var vy = new Array(num);
var x = new Array(num);
var y = new Array(num);
var ax = new Array(num);
var ay = new Array(num);

var magnetism = 15.0; //引力の強さ マイナスにすると斥力になる。
var radius = 1.0; //描画する円の半径
var gensoku = 0.9; // 粒子の移動を減速させる

///
let randSeedVal;

function setup() {
	randSeed = int(random(-99999, 99999));
	randomSeed(randSeed);
	randSeedVal = randSeed;
	console.log(randSeed);

	createCanvas(windowWidth, windowHeight);
	noStroke();
	fill(0);
	ellipseMode(RADIUS);
	background(0);
	blendMode(SCREEN); /// ADD

	for (var i = 0; i < num; i++) {
		x[i] = random(width + 1000);
		y[i] = random(height + 1000);
		vx[i] = 0;
		vy[i] = 0;
		ax[i] = 0;
		ay[i] = 0;
	}
}


frameCounter = 0
let posX, posY;
let holdParam = 1;
let rr, gg, bb;
rr = 0;
gg = 64;
bb = 128;

let offsetX = 2000;
let offsetY = 2000;

function draw() {
	if (frameCounter % holdParam === 0) {
		posX = random(-offsetX, width + offsetX); //random(0, width);
		posY = random(-offsetY, height + offsetY); //random(0, height);

		// don't converge in canvas
		while (posX > 0 && posX < width) {
			posX = random(-offsetX, width + offsetX);
		}
		while (posY > 0 && posY < height) {
			posY = random(-offsetY, height + offsetY);
		}

		holdParam = int(random(150, 250));
		magnetism = random(15, 35) - holdParam / 50;
		gensoku = random(0.8, 0.99);
		radius = random(0.4, 0.8);

		//colors
		rr = int(random(0, 255));
		gg = int(random(0, 255));
		bb = int(random(0, 255));
	}
	// posX = noise(random(0, width), touchX, 0); //noise(touchX)*width;
	// posY = noise(random(0, height), touchY, 0);// noise(touchY)*height;
	// posX = int(posX*width);
	// posY = int(posY*height);
	frameCounter++;

	fill(0, 0, 0);
	rect(0, 0, width, height);

	for (var i = 0; i < num; i++) {
		var distance = dist(posX, posY, x[i], y[i]); //dist(x1,y1,x2,y2) ２点間の距離を求める関数
		//加速度は引力の中心からの距離の二乗に反比例する。
		if (distance > 3) { //あまりマウスに近すぎる場合は加速度を更新しない
			ax[i] = magnetism * (posX - x[i]) / (distance ** 2);
			ay[i] = magnetism * (posY - y[i]) / (distance ** 2);
		}
		vx[i] += ax[i]; // 1フレームあたりaxだけ速度vxを増加する。
		vy[i] += ay[i]; // 1フレームあたりayだけ速度vyを増加する.

		vx[i] = vx[i] * gensoku;
		vy[i] = vy[i] * gensoku;

		x[i] += vx[i]; // 1フレームあたりvyピクセル進ませる。
		y[i] += vy[i]; // 1フレームあたりvyピクセル進ませる。

		var sokudo = dist(0, 0, vx[i], vy[i]); // 速度のX,Y成分から速度を求める
		var r = map(sokudo, 0, 5, rr, 255); //速度に応じた色を計算
		var g = map(sokudo, 0, 5, gg, 255);
		var b = map(sokudo, 0, 5, bb, 255);
		fill(r, g, b, 12, 0.5);
		ellipse(x[i], y[i], radius, radius);
	}

}


function mousePressed() {
	saveCanvas("seed" + str(randSeedVal) + "frame" + str(frameCount), "png");
}

